SELECT
    SUM(tr.amount) AS total,
    tr.type AS type,
    COALESCE(cg.name, '미분류') AS name
FROM
    transaction tr
    LEFT JOIN category cg ON tr.category_seq = cg.id
WHERE
    1=1
    AND tr.user_seq = #{userSeq, javaType=Long, jdbcType=BIGINT}
    AND tr.transaction_date BETWEEN #{startDate, javaType=String, jdbcType=VARCHAR}
                               AND #{endDate, javaType=String, jdbcType=VARCHAR}

    AND tr.category_seq IN

        #{cid, javaType=Long, jdbcType=BIGINT}



    AND LOWER(tr.description) LIKE CONCAT('%', LOWER(#{keyword, jdbcType=VARCHAR}), '%')


    AND tr.amount >= #{minAmount, jdbcType=DECIMAL}


    AND tr.amount <= #{maxAmount, jdbcType=DECIMAL}

GROUP BY
    tr.category_seq, tr.type

SELECT
    SUM(tr.amount) AS total,
    tr.type AS type,
    SUBSTRING(tr.transaction_date, 1, 6) AS transaction_date
FROM
    transaction tr
    LEFT JOIN category cg ON tr.category_seq = cg.id
WHERE
    1=1
    AND tr.user_seq = #{userSeq, javaType=Long, jdbcType=BIGINT}
    AND tr.transaction_date BETWEEN #{startDate, javaType=String, jdbcType=VARCHAR}
                               AND #{endDate, javaType=String, jdbcType=VARCHAR}

    AND tr.category_seq IN

        #{cid, javaType=Long, jdbcType=BIGINT}



    AND LOWER(tr.description) LIKE CONCAT('%', LOWER(#{keyword, jdbcType=VARCHAR}), '%')


    AND tr.amount >= #{minAmount, jdbcType=DECIMAL}


    AND tr.amount <= #{maxAmount, jdbcType=DECIMAL}

GROUP BY
    SUBSTRING(tr.transaction_date, 1, 6), tr.type
